```text
def flatten_list(list):
    """
    Flatten a nested list
    :param list: the nested list to flatten
    :return: a flattened list
    """
    flattened_list = []
    for item in list:
        if isinstance(item, list):
            flattened_list.extend(flatten_list(item))
        else:
