function validatePassword(password) {
  // Minimum 8 characters, one uppercase letter, one lowercase letter, one number, and one special character
  const re = /^(?=.*[a-z])(?=.*[A-Z])(?=.*[0-9])(?=.*[!@#\$%\^&\*])(?=.{8,})/;
  if (password.match(re)) {
    return true;
  }
  return false;
}
