public class Largest { 
  
    static int getLargest(int[] inputArray){ 
        int largest = inputArray[0]; 
        for(int i = 1; i < inputArray.length; i++){ 
            if(inputArray[i] > largest){ 
                largest = inputArray[i]; 
            } 
        } 
        return largest; 
    } 
      
    public static void main(String[] args){ 
