// Java program to find sum of elements in a matrix 
public class Matrix 
{ 
	public static void main(String[] args) 
	{ 
		// Initialize matrix 
		int[][] matrix = {{1, 2, 3}, 
						{4, 5, 6}, 
						{7, 8, 9}}; 

		// Initialize sum 
		int sum = 0; 

		// Compute sum of elements 
		for (int i = 0; i < 3; i++) 
			for (int j = 0; j < 3; j++) 
				sum = sum + matrix[i][j]; 

		// Print Sum 
		System.out.println("Sum of elements is: " + sum); 
	} 
}
