#include <iostream>
#include <string>

std::string capitalize(std::string s)
{
 std::string result;
 for (int i = 0; i < s.length(); i++) {
 if (i == 0 || s[i - 1] == '' '')
 result += toupper(s[i]);
 else
 result += s[i];
 }
 return result;
}
```

