def deleteNode(head, node):
 prev = None
 current = head
 # traverse the list until node is found
 while current is not None:
  if current.data == node:
  break
  prev = current
  current = current.next
 # if the node is the first node
 if prev is None:
  head = current.next
 else:
 prev.next = current.next
 return head

head = {
 data: 10,
 next : { 
  data: 21, 
  next: { 
   data: 14, 
   next: { 
    data: 35, 
    next: { 
     data: 19, 
     next: { 
      data: 63, 
      next: None
     } 
   }
 }
}
}

print(deleteNode(head, 14)) 

Output:
data: 10,
next : { 
  data: 21, 
  next: { 
