```text
public class Maximum {
	public static int findMax(int[] arr) {
		int max = arr[0];
		for(int i = 1; i < arr.length; i++) {
			if(arr[i] > max)
				max = arr[i];
		}
		return max;
	}

	public static void main(String args[]) {
		int arr[] = {2, 3, 1, 4, 5};
		int max = findMax(arr);
