public static int fibonacci(int n) 
{ 
    if (n <= 1) 
       return n; 
    return fibonacci(n-1) + fibonacci(n-2); 
} 
  
// Print first 10 numbers of the fibonacci sequence
for (int i = 0; i < 10; i++) 
    System.out.println(fibonacci(i));
