```text
using System;
using System.Data;
using MySql.Data.MySqlClient;

namespace DatabaseReader
{
    class Program
    {
        static void Main(string[] args)
        {
            try 
            {
                // Database connection
                string connString = "server=localhost; user id=root; database=DatabaseName";
                MySqlConnection mySQLConn = new MySqlConnection(connString);
                mySQLConn.Open();

                // SQL statement to execute
                string sql = "select ColumnName, ColumnName2 from TableName";
                MySqlDataAdapter dbAdapter = new MySqlDataAdapter(sql, mySQLConn);
                DataTable dbTable = new DataTable();
                dbAdapter.Fill(dbTable);

                // Display table header
                for (int i = 0; i < dbTable.Columns.Count; i++)
                {
                    Console.Write(dbTable.Columns[i].ColumnName + "\t");
                }
                Console.WriteLine();

                // Display table contents
                foreach (DataRow row in dbTable.Rows)
                {
                    foreach(object item in row.ItemArray) {
                        Console.Write(item + "\t");
                    }
                    Console.WriteLine();
                }

                //Close database connection
                mySQLConn.Close();
            } 
            catch (Exception ex)
            {
                Console.WriteLine(ex.Message);
            }
        }
    }
}
```

