```text
public class longestWord{
  public static void main(String[] args) {
 
    String inputStr = "Hello my name is John";
    String[] words = inputStr.split(" ");
 
    String longestWord = "";
    int maxLength = 0;
 
    for (String w : words){
      if (w.length() > maxLength) {
        maxLength = w.length();
        longestWord = w;
      }
  }
      System.out.println("Longest Word: "+ longestWord);
  }
}
