```text
// Function to validate a given string 
function validate(str) { 
    
    // Regex pattern to check if the string has any special characters 
    let strRegex = /^[A-Za-z]+$/; 
  
    // Check if the string is valid 
    if(strRegex.test(str)) { 
        return true; 
    } 
    else { 
        return false; 
    } 
} 
  
// String to be validated 
let str = "Hello world"; 
  
// Function call 
let result = validate(str); 
  
