int main()  
{  
    int i, j;  
    cout << "The prime numbers between 1 and 100 are:";  
    for (i = 1; i <= 100; i++)  
    {  
        for (j = 2; j <= (i / 2); j++)  
        {     
            if (i % j == 0)  
                break;  
        }  
      
        // If the prime number is found  
