            cout << i << " ";  
    }  
    return 0;  
}
```

#### Verified Solution & Code Implementation
```text
#include <iostream>  
using namespace std;  
  
int main()  
{  
    int i, j;  
    cout << "The prime numbers between 1 and 100 are:";  
    for (i = 1; i <= 100; i++)  
    {  
        int isPrime = 1;
        for (j = 2; j <= (i / 2); j++)  
        {  
            if (i % j == 0)  
            {  
                isPrime = 0;  
                break;  
            }  
        }  
      
        if(isPrime == 1)  
            cout << i << " ";  
    }  
    return 0;  
}
```

