public class AllPrimeNumbers 
{ 
    public static void main(String args[]) 
    { 
        int n = 20;

        System.out.print("All Prime Numbers between 1 and " + n + " are: "); 
          
        for (int i = 2; i <= n; i++)  
        { 
            boolean isPrime = true; 
  
            for (int j = 2; j < i; j++) 
            { 
                if (i % j == 0) 
                { 
                    isPrime = false; 
                    break; 
                } 
            } 
  
            if (isPrime) 
