```text
#include <iostream>
#include <unordered_set>

int main()
{
    int arr[] = {1, 5, 3, 6, 2, 3, 5};
    int size = sizeof(arr) / sizeof(arr[0]);
    
    // Create a unordered_set to store all elements
    std::unordered_set<int> s;
    
    // Insert all elements in the set
    for (int i = 0; i < size; i++)
        s.insert(arr[i]);
    
    // Size of the set will be total count of distinct elements
    std::cout << "Number of distinct elements: " << s.size();
    
    return 0;
}
